import assert from 'node:assert/strict';
import {cpSync,mkdtempSync,readFileSync,rmSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
const root='/workspace/Tavotto-cla-ci-integration/services/cla-cloudflare';
const evidence='/tmp/tavotto-cla-ci-integration/final-escaped-regex';
const c=JSON.parse(readFileSync(path.join(root,'tests/ci-wait-mutation-cases.json'),'utf8')).find(c=>c.name==='pending exact response shape');
assert.ok(c && c.pattern.includes('\\') && c.pattern!==c.selectedTitle);
const tmp=mkdtempSync(path.join(os.tmpdir(),'cla-ci-escaped-regex-'));
const hash=data=>createHash('sha256').update(data).digest('hex');
try {
 for(const p of ['src','tests','scripts','migrations','deployment','package.json'])cpSync(path.join(root,p),path.join(tmp,p),{recursive:true});
 const file=path.join(tmp,c.file),before=readFileSync(file,'utf8');
 assert.equal(before.split(c.before).length-1,1,'unique source location before mutation');
 const after=before.replace(c.before,c.after);assert.notEqual(after,before);writeFileSync(file,after);assert.equal(readFileSync(file,'utf8'),after);
 const argv=['--test','--test-name-pattern='+c.pattern,c.testFile];
 const child=spawnSync(process.execPath,argv,{cwd:tmp,encoding:'utf8'});
 const raw=child.stdout+child.stderr;writeFileSync(path.join(evidence,'escaped-regex-mutant.raw.log'),raw);
 assert.equal(child.error,undefined);assert.equal(child.status,1);assert.ok(raw.includes('AssertionError'));
 assert.equal(raw.includes(c.pattern),false,'old escaped-pattern title witness cannot match emitted literal test title');
 assert.ok(raw.includes(c.selectedTitle??c.pattern),'literal selectedTitle witness matches the actually failed test');
 assert.throws(()=>assert.ok(raw.includes(c.pattern),'selected test was executed'),{code:'ERR_ASSERTION'});
 const result={case_name:c.name,argv,child_exit:child.status,actual_assertion_error:true,mutation_location_count:1,
  source_sha256:hash(before),mutated_sha256:hash(after),pattern:c.pattern,selectedTitle:c.selectedTitle,
  old_pattern_title_witness:false,new_selected_title_witness:true,old_harness_assertion_reproduced:true,
  changed_combination_source:false,network:false,publication:false,proof_expiry_transition:false};
 writeFileSync(path.join(evidence,'escaped-regex-witness.result.json'),JSON.stringify(result,null,2)+'\n');
 console.log(JSON.stringify(result,null,2));
} finally {rmSync(tmp,{recursive:true,force:true});}

